import { MakeLogicType, actions, kea, key, listeners, path, props, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import * as api from '../generated/api'
import type { ScoreDefinitionApi, ScoreDefinitionVersionApi } from '../generated/api.schemas'
import {
    createDraft,
    getApiErrorDetail,
    getCurrentProjectId,
    type ScoreDefinitionDraft,
} from './scoreDefinitionModalUtils'

export interface ScorerVersionHistoryLogicProps {
    definition: ScoreDefinitionApi
}

