export type scorerVersionHistoryLogicType = MakeLogicType<
    scorerVersionHistoryLogicValues,
    scorerVersionHistoryLogicActions,
    ScorerVersionHistoryLogicProps,
    scorerVersionHistoryLogicMeta
>

export const scorerVersionHistoryLogic = kea<scorerVersionHistoryLogicType>([
    props({} as ScorerVersionHistoryLogicProps),
    key(({ definition }) => definition.id),
    path((key) => ['products', 'ai_observability', 'scoreDefinitions', 'scorerVersionHistoryLogic', key]),
    actions({
        openHistory: true,
        closeHistory: true,
        selectVersion: (versionId: string) => ({ versionId }),
        loadVersions: (cursor?: string) => ({ cursor }),
    }),
    loaders(({ props, values }) => ({
        history: [
            {
                results: [] as ScoreDefinitionVersionApi[],
                nextCursor: null as string | null,
                error: null as string | null,
            },
            {
                loadVersions: async ({ cursor }, breakpoint) => {
                    try {
                        const page = await api.llmAnalyticsScoreDefinitionsVersionsList(
                            getCurrentProjectId(),
                            props.definition.id,
                            { cursor, limit: 50 }
                        )
                        breakpoint()
                        return {
                            results: cursor ? [...values.history.results, ...page.results] : page.results,
                            nextCursor: page.next_cursor,
                            error: null,
                        }
                    } catch (error) {
                        breakpoint()
                        return {
                            ...values.history,
                            error: getApiErrorDetail(error) || 'Could not load scorer versions.',
                        }
                    }
                },
            },
        ],
    })),
    reducers({
        isOpen: [false, { openHistory: () => true, closeHistory: () => false }],
        selectedVersionId: [
            null as string | null,
            { openHistory: () => null, selectVersion: (_, { versionId }) => versionId },
        ],
        cursor: [null as string | null, { loadVersions: (_, { cursor }) => cursor ?? null }],
    }),
    selectors({
        selectedVersion: [
            (s) => [s.history, s.selectedVersionId],
            (
                history: {
                    error: string | null
                    nextCursor: string | null
                    results: ScoreDefinitionVersionApi[]
                },
                selectedVersionId: string | null
            ): ScoreDefinitionVersionApi | null =>
                history.results.find((version: ScoreDefinitionVersionApi) => version.id === selectedVersionId) ||
                history.results[0] ||
                null,
        ],
        versionDraft: [
            (s) => [s.selectedVersion, (_, props) => props.definition],
            (version: ScoreDefinitionVersionApi | null, definition: ScoreDefinitionApi) =>
                version
                    ? createDraft('config', {
                          ...definition,
                          kind: version.kind,
                          calculation: version.calculation,
                          config: version.config,
                          composition: version.composition,
                          input_scorers: [],
                      })
                    : null,
        ],
    }),
    listeners(({ actions }) => ({ openHistory: () => actions.loadVersions() })),
])
